168	{
169	  uint32_t feat0 = getreg32(gmac_base + GMAC_HW_FEATURE0);
170	
171	  ninfo("HW_FEATURE0 = 0x%08" PRIX32 "\n", feat0);
172	  ninfo("  MII(10/100M): %s\n", (feat0 & (1 << 0)) ? "YES" : "NO");
173	
174	  if (feat0 == 0x00000000 || feat0 == 0xFFFFFFFF)
175	    {
176	      nerr("ERROR: Invalid HW_FEATURE0 value, base address wrong?\n");
177	      return -1;
178	    }
179	
180	  return 0;
