183	/****************************************************************************
184	 * Private Functions - DMA Software Reset
185	 ****************************************************************************/
186	
187	static int dma_soft_reset(uintptr_t gmac_base)
188	{
189	  uint32_t val;
190	  int timeout = 100000;
191	
192	  val = getreg32(gmac_base + DMA_BUS_MODE);
193	  putreg32(val | DMA_SFT_RESET, gmac_base + DMA_BUS_MODE);
194	
195	  do
196	    {
197	      val = getreg32(gmac_base + DMA_BUS_MODE);
198	      if (!(val & DMA_SFT_RESET))
199	        {
200	          return 0;
201	        }
202	
203	      up_udelay(10);
204	    }
205	  while (--timeout > 0);
206	
207	  nerr("ERROR: DMA reset timeout\n");
208	  return -1;
209	}
