358	static void ephy_hardware_reset(uintptr_t phy_base, uintptr_t phy_top)
359	{
360	  uint32_t apb_id1;
361	  uint32_t apb_id2;
362	
363	  ephy_led_pinmux();
364	
365	  /* Minimal EPHY init sequence, matches Linux bm_eth_reset_phy() in
366	   * dwmac-cvitek.c and U-Boot cv181x_ephy_id_init() in board.c.
367	   * This ONLY releases resets and programs the PHY ID — it does NOT
368	   * run the full analog tuning sequence.  The full tuning (which
369	   * accesses internal pages and starts auto-negotiation) must run
370	   * AFTER the MDIO interface is confirmed operational, just as
371	   * Linux does in cv182xa_phy_config_init() -> config_init callback.
372	   */
373	
374	  /* Select APB interface to access EPHY registers */
375	
376	  putreg32(0x0001, phy_top + 0x4);
377	
378	  /* Release shutdown */
379	
380	  putreg32(0x0900, phy_top);
381	
382	  /* Release dig_rst_n — enables MII register access via APB */
383	
384	  putreg32(0x0904, phy_top);
385	
386	  /* Switch to Page 5 for ANA init */
387	
388	  putreg32(0x0500, phy_base + 0x7c);
389	
390	  /* ANA_PD (power-down release) */
391	
392	  putreg32(0x0c00, phy_base + 0x40);
393	
394	  /* ANA_EN */
395	
396	  putreg32(0x0c7e, phy_base + 0x40);
397	  up_mdelay(1);
398	
399	  /* Release ana_rst_n */
400	
401	  putreg32(0x0906, phy_top);
402	  putreg32(0x0500, phy_base + 0x7c);
403	
404	  /* Program PHY ID into EPHY registers (so MDIO can discover it) */
405	
406	  putreg32(0x0043, phy_base + 0x08);  /* PHY_ID_HIGH */
407	  putreg32(0x5649, phy_base + 0x0c);  /* PHY_ID_LOW */
408	
409	  /* Read back PHY ID via APB for diagnostic verification */
410	
411	  apb_id1 = getreg32(phy_base + 0x08) & 0xffff;
412	  apb_id2 = getreg32(phy_base + 0x0c) & 0xffff;
413	  syslog(LOG_INFO, "sg2000_eth: EPHY APB PHYID=0x%04" PRIX32
414	         "%04" PRIX32 "\n", apb_id1, apb_id2);
415	
416	  /* Switch control to MDIO (GMAC) so the DWMAC4 MDIO controller can
417	   * discover and communicate with the PHY.
418	   */
419	
420	  putreg32(0x0000, phy_top + 0x4);
421	  up_mdelay(10);
422	
423	  syslog(LOG_INFO, "sg2000_eth: EPHY init done top=0x%08" PRIX32
424	         " sel=0x%08" PRIX32 "\n",
425	         getreg32(phy_top), getreg32(phy_top + 0x4));
426	}
