428	/****************************************************************************
429	 * Name: ephy_full_tuning
430	 *
431	 * Description:
432	 *   Run the full CV182XA analog tuning sequence via APB, then switch back
433	 *   to MDIO control.  Matches Linux cv182xa_phy_config_init().
434	 *   MUST be called AFTER MDIO is confirmed operational, as it accesses
435	 *   internal pages and starts auto-negotiation which can interfere with
436	 *   MDIO if run before the MDIO interface is active.
437	 *
438	 ****************************************************************************/
439	
440	static void ephy_full_tuning(uintptr_t phy_base, uintptr_t phy_top)
441	{
442	  /* ephy_full_analog_init expects APB mode; caller ensures MDIO is working
443	   * before we switch to APB for tuning.
444	   */
445	
446	  putreg32(0x0001, phy_top + 0x4);
447	  ephy_full_analog_init(phy_base, phy_top);
448	
449	  /* ephy_full_analog_init ends with:
450	   *   page 0 + autoneg start (0x090e) + force full-duplex
451	   * Switch control back to MDIO so the GMAC can manage the PHY.
452	   */
453	
454	  putreg32(0x0000, phy_top + 0x4);
455	  up_mdelay(10);
456	
457	  syslog(LOG_INFO, "sg2000_eth: EPHY full tuning done, top=0x%08" PRIX32
458	         " sel=0x%08" PRIX32 "\n",
459	         getreg32(phy_top), getreg32(phy_top + 0x4));
460	}
