528	static void mdio_diag_scan(uintptr_t gmac_base)
529	{
530	  int phy;
531	
532	  for (phy = 0; phy < 32; phy++)
533	    {
534	      bool to1;
535	      bool to2;
536	      uint16_t id1 = mdio_read_status(gmac_base, phy, 2, &to1);
537	      uint16_t id2 = mdio_read_status(gmac_base, phy, 3, &to2);
538	      uint32_t id = ((uint32_t)id1 << 16) | id2;
539	
540	      syslog(LOG_INFO, "sg2000_eth: MDIO scan phy=%d id=0x%08" PRIX32
541	             " timeout=%d/%d\n", phy, id, to1 ? 1 : 0, to2 ? 1 : 0);
542	    }
543	}
