545	static void mdio_write(uintptr_t gmac_base, int phy_addr, int reg,
546	                       uint16_t data)
547	{
548	  uint32_t cmd;
549	  int timeout = 10000;
550	
551	  putreg32(data, gmac_base + GMAC_MDIO_DATA);
552	  cmd = (((uint32_t)phy_addr << GMAC_MDIO_PA_SHIFT) & GMAC_MDIO_PA_MASK) |
553	        (((uint32_t)reg << GMAC_MDIO_RDA_SHIFT) & GMAC_MDIO_RDA_MASK) |
554	        GMAC_MDIO_CR_250_300M | GMAC_MDIO_GOC_WRITE | GMAC_MDIO_BUSY;
555	  putreg32(cmd, gmac_base + GMAC_MDIO_ADDR);
556	
557	  do
558	    {
559	      if (!(getreg32(gmac_base + GMAC_MDIO_ADDR) & GMAC_MDIO_BUSY))
560	        {
561	          break;
562	        }
563	
564	      up_udelay(1);
565	    }
566	  while (--timeout > 0);
567	}
