573	static int phy_config_init(struct sg2000_eth_priv_s *priv)
574	{
575	  uint16_t bmsr;
576	  uint16_t bmcr;
577	  uint16_t anlpar;
578	  int timeout;
579	
580	  /* Read PHY ID */
581	
582	  uint16_t id1 = mdio_read(priv->gmac_base, 0, 2);
583	  uint16_t id2 = mdio_read(priv->gmac_base, 0, 3);
584	  uint32_t phy_id = (id1 << 16) | id2;
585	
586	  syslog(LOG_INFO, "sg2000_eth: PHY ID=0x%08" PRIX32
587	         " expect=0x00435649\n", phy_id);
588	
589	  if (phy_id == 0xffffffff)
590	    {
591	      syslog(LOG_ERR, "sg2000_eth: PHY not responding\n");
592	      mdio_diag_scan(priv->gmac_base);
593	      return -1;
594	    }
595	
596	  if (phy_id != CVITEK_PHY_ID)
597	    {
598	      syslog(LOG_WARNING, "sg2000_eth: unexpected PHY ID 0x%08" PRIX32
599	             "\n", phy_id);
600	    }
601	
602	  priv->speed = 100;
603	  priv->duplex = 1;
604	
605	  /* Reset PHY */
606	
607	  mdio_write(priv->gmac_base, 0, 0, 0x8000);
608	  up_mdelay(10);
609	
610	  timeout = 100;
611	  do
612	    {
613	      bmcr = mdio_read(priv->gmac_base, 0, 0);
614	      if (!(bmcr & 0x8000))
615	        {
616	          break;
617	        }
618	
619	      up_mdelay(1);
620	    }
621	  while (--timeout > 0);
622	
623	  syslog(LOG_INFO, "sg2000_eth: PHY reset done, BMCR=0x%04X\n", bmcr);
624	
625	  /* Advertise 10/100 Full Duplex */
626	
627	  mdio_write(priv->gmac_base, 0, 4, 0x01e1);
628	
629	  /* Start auto-negotiation */
630	
631	  bmcr = mdio_read(priv->gmac_base, 0, 0);
632	  mdio_write(priv->gmac_base, 0, 0, bmcr | 0x1200);
633	  syslog(LOG_INFO, "sg2000_eth: autoneg start, BMCR=0x%04X\n",
634	         bmcr | 0x1200);
635	
636	  /* Wait for link.  BMSR link status is latch-low, so read it twice. */
637	
638	  timeout = 50;
639	  do
640	    {
641	      (void)mdio_read(priv->gmac_base, 0, 1);
642	      bmsr = mdio_read(priv->gmac_base, 0, 1);
643	      if ((bmsr & 0x0004) != 0)
644	        {
645	          break;
646	        }
647	
648	      up_mdelay(100);
649	    }
650	  while (--timeout > 0);
651	
652	  if ((bmsr & 0x0004) == 0)
653	    {
654	      syslog(LOG_WARNING, "sg2000_eth: PHY link down, BMSR=0x%04X\n",
655	             bmsr);
656	      priv->link_up = 0;
657	      return OK;
658	    }
659	
660	  anlpar = mdio_read(priv->gmac_base, 0, 5);
661	  syslog(LOG_INFO, "sg2000_eth: PHY link detected, BMSR=0x%04X "
662	         "ANLPAR=0x%04X\n", bmsr, anlpar);
663	
664	  if ((bmsr & 0x0020) == 0)
665	    {
666	      syslog(LOG_WARNING, "sg2000_eth: PHY autoneg incomplete, "
667	             "BMSR=0x%04X\n", bmsr);
668	    }
669	
670	  if ((anlpar & 0x0100) != 0)
671	    {
672	      priv->speed = 100;
673	      priv->duplex = 1;  /* Full */
674	    }
675	  else if ((anlpar & 0x0080) != 0)
676	    {
677	      priv->speed = 100;
678	      priv->duplex = 0;  /* Half */
679	    }
680	  else if ((anlpar & 0x0040) != 0)
681	    {
682	      priv->speed = 10;
683	      priv->duplex = 1;  /* Full */
684	    }
685	  else
686	    {
687	      priv->speed = 10;
688	      priv->duplex = 0;  /* Half */
689	    }
690	
691	  priv->link_up = 1;
692	  syslog(LOG_INFO, "sg2000_eth: PHY link up: %d Mbps %s duplex\n",
693	         priv->speed, priv->duplex ? "Full" : "Half");
694	  return 0;
695	}
