697	/****************************************************************************
698	 * Private Functions - DMA Descriptor Management
699	 ****************************************************************************/
700	
701	static int alloc_dma(struct sg2000_eth_priv_s *priv)
702	{
703	  int i;
704	
705	  priv->tx_desc = kmm_memalign(16, TX_RING_SIZE *
706	                                sizeof(struct sg2000_dma_desc_s));
707	  priv->rx_desc = kmm_memalign(16, RX_RING_SIZE *
708	                                sizeof(struct sg2000_dma_desc_s));
709	
710	  if (!priv->tx_desc || !priv->rx_desc)
711	    {
712	      return -ENOMEM;
713	    }
714	
715	  memset(priv->tx_desc, 0, TX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
716	  memset(priv->rx_desc, 0, RX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
717	
718	  /* For MMU-less or identity-mapped platforms, virtual address = physical.
719	   * TODO: For strict MMU kernel builds, use mm_virt_to_phys().
720	   */
721	
722	  priv->tx_desc_phys = (uint32_t)(uintptr_t)priv->tx_desc;
723	  priv->rx_desc_phys = (uint32_t)(uintptr_t)priv->rx_desc;
724	
725	  for (i = 0; i < TX_RING_SIZE; i++)
726	    {
727	      priv->tx_buf[i] = kmm_memalign(4, TX_BUF_SIZE);
728	      if (!priv->tx_buf[i])
729	        {
730	          return -ENOMEM;
731	        }
732	
733	      priv->tx_pkt[i] = NULL;
734	    }
735	
736	  for (i = 0; i < RX_RING_SIZE; i++)
737	    {
738	      priv->rx_buf[i] = kmm_memalign(4, RX_BUF_SIZE);
739	      if (!priv->rx_buf[i])
740	        {
741	          return -ENOMEM;
742	        }
743	    }
744	
745	  return 0;
746	}
747	
748	static void init_desc_and_dma(struct sg2000_eth_priv_s *priv)
749	{
750	  uintptr_t base = priv->gmac_base;
751	  uintptr_t dma = base + DMA_CHAN_BASE;
752	  int i;
753	
754	  /* Initialize TX descriptors */
755	
756	  for (i = 0; i < TX_RING_SIZE; i++)
757	    {
758	      priv->tx_desc[i].des0 = 0;
759	      priv->tx_desc[i].des2 = (uint32_t)(uintptr_t)priv->tx_buf[i];
760	      priv->tx_pkt[i] = NULL;
761	    }
762	
763	  /* Initialize RX descriptors: set OWN=1 (DMA owns them, can write) */
764	
765	  for (i = 0; i < RX_RING_SIZE; i++)
766	    {
767	      priv->rx_desc[i].des0 = DESC_OWN;
768	      priv->rx_desc[i].des1 = RX_BUF_SIZE;
769	      priv->rx_desc[i].des2 = (uint32_t)(uintptr_t)priv->rx_buf[i];
770	    }
771	
772	  priv->tx_cur = 0;
773	  priv->tx_dirty = 0;
774	  priv->rx_cur = 0;
775	
776	  /* Program DMA registers */
777	
778	  putreg32(DMA_SYS_DEFAULT, base + DMA_SYS_BUS_MODE);
779	  putreg32(TX_RING_SIZE - 1, dma + DMA_CHAN_TX_RING_LEN);
780	  putreg32(RX_RING_SIZE - 1, dma + DMA_CHAN_RX_RING_LEN);
781	  putreg32(priv->tx_desc_phys, dma + DMA_CHAN_TX_BASE_ADDR);
782	  putreg32(priv->rx_desc_phys, dma + DMA_CHAN_RX_BASE_ADDR);
783	  putreg32(DMA_INTR_DEFAULT_MASK, dma + DMA_CHAN_INTR_ENA);
784	}
785	
786	/****************************************************************************
787	 * Private Functions - MAC and DMA Control
788	 ****************************************************************************/
789	
790	static void set_mac_addr(uintptr_t gmac_base, const uint8_t *mac)
791	{
792	  uint32_t hi;
793	  uint32_t lo;
794	
795	  hi = (mac[5] << 8) | mac[4] | GMAC_HI_REG_AE;
796	  lo = (mac[3] << 24) | (mac[2] << 16) | (mac[1] << 8) | mac[0];
797	
798	  putreg32(hi, gmac_base + GMAC_ADDR_HIGH(0));
799	  putreg32(lo, gmac_base + GMAC_ADDR_LOW(0));
800	}
801	
802	static void start_mac_and_dma(struct sg2000_eth_priv_s *priv)
803	{
804	  uintptr_t gmac_base = priv->gmac_base;
805	  uintptr_t dma = gmac_base + DMA_CHAN_BASE;
806	  uint32_t v;
807	
808	  /* Configure MAC based on PHY negotiation results */
809	
810	  v = GMAC_CORE_INIT;
811	  if (priv->speed == 100)
812	    {
813	      v |= GMAC_CONFIG_FES;   /* 100M */
814	    }
815	
816	  if (priv->duplex)
817	    {
818	      v |= GMAC_CONFIG_DM;    /* Full duplex */
819	    }
820	
821	  putreg32(v, gmac_base + GMAC_CONFIG);
822	
823	  /* Packet filter: pass multicast + broadcast + unicast to us */
824	
825	  putreg32(GMAC_FILTER_HMC | GMAC_FILTER_PM | GMAC_FILTER_PR,
826	           gmac_base + GMAC_PACKET_FILTER);
827	
828	  /* Enable MAC interrupts */
829	
830	  putreg32(GMAC_INT_DEFAULT, gmac_base + GMAC_INT_EN);
831	
832	  /* Enable MAC TX and RX */
833	
834	  v = getreg32(gmac_base + GMAC_CONFIG);
835	  putreg32(v | GMAC_CONFIG_TE | GMAC_CONFIG_RE, gmac_base + GMAC_CONFIG);
836	
837	  /* Start TX DMA */
838	
839	  v = getreg32(dma + DMA_CHAN_TX_CONTROL);
840	  putreg32(v | DMA_TX_ST, dma + DMA_CHAN_TX_CONTROL);
841	
842	  /* Start RX DMA */
843	
844	  v = getreg32(dma + DMA_CHAN_RX_CONTROL);
845	  putreg32(v | DMA_RX_SR, dma + DMA_CHAN_RX_CONTROL);
846	}
