848	/****************************************************************************
849	 * Private Functions - Doorbell Helpers
850	 ****************************************************************************/
851	
852	static void tx_doorbell(struct sg2000_eth_priv_s *priv)
853	{
854	  uint32_t tail = priv->tx_desc_phys +
855	                  priv->tx_cur * sizeof(struct sg2000_dma_desc_s);
856	
857	  putreg32(tail, priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_END_ADDR);
858	}
859	
860	static void rx_doorbell(struct sg2000_eth_priv_s *priv)
861	{
862	  uint32_t tail = priv->rx_desc_phys +
863	                  priv->rx_cur * sizeof(struct sg2000_dma_desc_s);
864	
865	  putreg32(tail, priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_END_ADDR);
866	}
867	
868	/****************************************************************************
869	 * Private Functions - Hardware Transmit
870	 ****************************************************************************/
871	
872	static int hw_transmit(struct sg2000_eth_priv_s *priv,
873	                       const uint8_t *data, int len)
874	{
875	  unsigned int idx = priv->tx_cur;
876	  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
877	  irqstate_t flags;
878	
879	  /* Check if the ring is full */
880	
881	  if (desc->des0 & DESC_OWN)
882	    {
883	      return -EBUSY;
884	    }
885	
886	  /* Copy data to DMA TX buffer */
887	
888	  memcpy(priv->tx_buf[idx], data, len);
889	
890	  desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];
891	  desc->des1 = len;
892	
893	  /* OWN | First Segment | Last Segment | Interrupt on Completion */
894	
895	  desc->des0 = DESC_OWN | TX_DESC_FS | TX_DESC_LS | TX_DESC_IC |
896	               (len & RX_DESC_FL_MASK);
897	
898	  flags = up_irq_save();
899	  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);
900	
901	  /* Memory barrier: ensure descriptor is visible to DMA engine */
902	
903	  __asm__ volatile ("fence w,w" ::: "memory");
904	
905	  tx_doorbell(priv);
906	  up_irq_restore(flags);
907	
908	  return 0;
909	}
910	
911	/****************************************************************************
912	 * Private Functions - TX Cleanup (called from ISR on TX complete)
913	 ****************************************************************************/
914	
915	static void tx_cleanup(struct sg2000_eth_priv_s *priv)
916	{
917	  irqstate_t flags = up_irq_save();
918	
919	  while (priv->tx_dirty != priv->tx_cur)
920	    {
921	      struct sg2000_dma_desc_s *desc = &priv->tx_desc[priv->tx_dirty];
922	
923	      if (desc->des0 & DESC_OWN)
924	        {
925	          /* Still owned by DMA, stop */
926	
927	          break;
928	        }
929	
930	      /* Check for TX errors */
931	
932	      if (desc->des0 & TX_DESC_ES)
933	        {
934	          nerr("ERROR: TX error, status=0x%08" PRIX32 "\n", desc->des0);
935	        }
936	
937	      /* Free the netpkt if we have one tracked for this slot */
938	
939	      if (priv->tx_pkt[priv->tx_dirty] != NULL)
940	        {
941	          netpkt_free(&priv->dev, priv->tx_pkt[priv->tx_dirty], NETPKT_TX);
942	          priv->tx_pkt[priv->tx_dirty] = NULL;
943	
944	          /* Notify upper half that TX is done */
945	
946	          netdev_lower_txdone(&priv->dev);
947	        }
948	
949	      /* Move to next descriptor */
950	
951	      priv->tx_dirty = (priv->tx_dirty + 1) & (TX_RING_SIZE - 1);
952	    }
953	
954	  up_irq_restore(flags);
955	}
956	
957	/****************************************************************************
958	 * Private Functions - ISR
959	 ****************************************************************************/
960	
961	static int sg2000_eth_isr(int irq, void *context, void *arg)
962	{
963	  struct sg2000_eth_priv_s *priv = (struct sg2000_eth_priv_s *)arg;
964	  uintptr_t base = priv->gmac_base;
965	  uintptr_t dma = base + DMA_CHAN_BASE;
966	  uint32_t status;
967	  uint32_t intr_en;
968	  uint32_t mac;
969	
970	  /* Clear MAC interrupts */
971	
972	  mac = getreg32(base + GMAC_INT_STATUS);
973	  if (mac)
974	    {
975	      putreg32(mac, base + GMAC_INT_STATUS);
976	    }
977	
978	  /* Read DMA channel status (only enabled interrupts) */
979	
980	  intr_en = getreg32(dma + DMA_CHAN_INTR_ENA);
981	  status = getreg32(dma + DMA_CHAN_STATUS) & intr_en;
982	
983	  if (!status)
984	    {
985	      return OK;
986	    }
987	
988	  /* Write-1-to-clear the status bits */
989	
990	  putreg32(status, dma + DMA_CHAN_STATUS);
991	
992	  if (status & DMA_STATUS_NIS)
993	    {
994	      /* Normal interrupt */
995	
996	      if (status & DMA_STATUS_RI)
997	        {
998	          /* RX complete: notify upper half that packets are ready.
999	           * The upper half will call our receive() callback to get them.
1000	           */
1001	
1002	          netdev_lower_rxready(&priv->dev);
1003	        }
1004	
1005	      if (status & DMA_STATUS_TI)
1006	        {
1007	          /* TX complete: cleanup descriptors and notify upper half */
1008	
1009	          tx_cleanup(priv);
1010	        }
1011	    }
1012	
1013	  if (status & DMA_STATUS_AIS)
1014	    {
1015	      /* Abnormal interrupt */
1016	
1017	      nerr("ERROR: DMA Abnormal: 0x%08" PRIX32 "\n", status);
1018	
1019	      if (status & DMA_STATUS_RBU)
1020	        {
1021	          nerr("ERROR: RX Buffer Unavailable\n");
1022	        }
1023	
1024	      if (status & DMA_STATUS_TPS)
1025	        {
1026	          nerr("ERROR: TX Process Stopped\n");
1027	        }
1028	
1029	      if (status & DMA_STATUS_FBE)
1030	        {
1031	          nerr("ERROR: Fatal Bus Error\n");
1032	        }
1033	    }
1034	
1035	  return OK;
1036	}
