1038	/****************************************************************************
1039	 * Name: netdriver_ifup
1040	 *
1041	 * Description:
1042	 *   OpenVela netdev_ops_s ifup callback.  Starts the network device.
1043	 *
1044	 ****************************************************************************/
1045	
1046	static int netdriver_ifup(FAR struct netdev_lowerhalf_s *dev)
1047	{
1048	  FAR struct sg2000_eth_priv_s *priv =
1049	      (FAR struct sg2000_eth_priv_s *)dev;
1050	  int ret;
1051	
1052	  syslog(LOG_INFO, "sg2000_eth: ifup begin\n");
1053	
1054	  /* Ensure GMAC clocks and resets are configured */
1055	
1056	  gmac_clock_enable();
1057	
1058	  /* Set MAC core init (includes PS=MII mode) before PHY/MDIO operations.
1059	   * The DWMAC4 MDIO controller uses the CSR clock domain configured here.
1060	   */
1061	
1062	  putreg32(GMAC_CORE_INIT, priv->gmac_base + GMAC_CONFIG);
1063	
1064	  ret = dma_soft_reset(priv->gmac_base);
1065	  if (ret < 0)
1066	    {
1067	      nerr("ERROR: DMA reset failed before PHY init: %d\n", ret);
1068	      return ret;
1069	    }
1070	
1071	  ephy_hardware_reset(priv->phy_base, priv->phy_top);
1072	  up_mdelay(10);
1073	
1074	  syslog(LOG_INFO, "sg2000_eth: MDIO before PHY init addr=0x%08" PRIX32
1075	         " data=0x%08" PRIX32 "\n",
1076	         getreg32(priv->gmac_base + GMAC_MDIO_ADDR),
1077	         getreg32(priv->gmac_base + GMAC_MDIO_DATA));
1078	
1079	  /* Verify MDIO is working before running the full analog tuning.
1080	   * The full tuning accesses internal pages via APB and starts
1081	   * auto-negotiation, which can interfere with MDIO if the interface
1082	   * is not yet operational.
1083	   */
1084	
1085	  {
1086	    uint16_t check_id1 = mdio_read(priv->gmac_base, 0, 2);
1087	    uint16_t check_id2 = mdio_read(priv->gmac_base, 0, 3);
1088	    uint32_t check_phy_id = (check_id1 << 16) | check_id2;
1089	
1090	    if (check_phy_id != 0xffffffff && check_phy_id != 0x00000000)
1091	      {
1092	        ephy_full_tuning(priv->phy_base, priv->phy_top);
1093	      }
1094	    else
1095	      {
1096	        syslog(LOG_WARNING, "sg2000_eth: MDIO check failed, skipping "
1097	               "full tuning (id=0x%08" PRIX32 ")\n", check_phy_id);
1098	      }
1099	  }
1100	
1101	  ret = phy_config_init(priv);
1102	  if (ret < 0)
1103	    {
1104	      nerr("ERROR: PHY init failed: %d\n", ret);
1105	      return ret;
1106	    }
1107	
1108	  if (priv->tx_desc == NULL || priv->rx_desc == NULL)
1109	    {
1110	      ret = alloc_dma(priv);
1111	      if (ret < 0)
1112	        {
1113	          nerr("ERROR: alloc_dma failed: %d\n", ret);
1114	          return ret;
1115	        }
1116	    }
1117	
1118	  init_desc_and_dma(priv);
1119	  set_mac_addr(priv->gmac_base, priv->mac_addr);
1120	  start_mac_and_dma(priv);
1121	  rx_doorbell(priv);
1122	
1123	  up_enable_irq(priv->irq);
1124	  if (priv->link_up)
1125	    {
1126	      netdev_lower_carrier_on(dev);
1127	    }
1128	  else
1129	    {
1130	      netdev_lower_carrier_off(dev);
1131	    }
1132	
1133	  syslog(LOG_INFO, "sg2000_eth: ifup done, %d Mbps %s duplex\n",
1134	         priv->speed, priv->duplex ? "Full" : "Half");
1135	
1136	  return OK;
1137	}
1138	
1139	/****************************************************************************
1140	 * Name: netdriver_ifdown
1141	 *
1142	 * Description:
1143	 *   OpenVela netdev_ops_s ifdown callback.  Stops the network device.
1144	 *
1145	 ****************************************************************************/
1146	
1147	static int netdriver_ifdown(FAR struct netdev_lowerhalf_s *dev)
1148	{
1149	  FAR struct sg2000_eth_priv_s *priv =
1150	      (FAR struct sg2000_eth_priv_s *)dev;
1151	  uint32_t v;
1152	
1153	  up_disable_irq(priv->irq);
1154	
1155	  /* Stop TX DMA */
1156	
1157	  v = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL);
1158	  putreg32(v & ~DMA_TX_ST,
1159	           priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL);
1160	
1161	  /* Stop RX DMA */
1162	
1163	  v = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL);
1164	  putreg32(v & ~DMA_RX_SR,
1165	           priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL);
1166	
1167	  /* Disable MAC TX/RX */
1168	
1169	  v = getreg32(priv->gmac_base + GMAC_CONFIG);
1170	  putreg32(v & ~(GMAC_CONFIG_TE | GMAC_CONFIG_RE),
1171	           priv->gmac_base + GMAC_CONFIG);
1172	
1173	  netdev_lower_carrier_off(dev);
1174	
1175	  ninfo("netdriver_ifdown: interface down\n");
1176	
1177	  return OK;
1178	}
1179	
1180	/****************************************************************************
1181	 * Name: netdriver_transmit
1182	 *
1183	 * Description:
1184	 *   OpenVela netdev_ops_s transmit callback.  Sends a packet.
1185	 *   The driver takes ownership of the netpkt and MUST free it after TX
1186	 *   completion (or on error).
1187	 *
1188	 *   Returned Value:
1189	 *     OK on success (pkt queued for TX); negated errno on failure.
1190	 *
1191	 ****************************************************************************/
1192	
1193	static int netdriver_transmit(FAR struct netdev_lowerhalf_s *dev,
1194	                               FAR netpkt_t *pkt)
1195	{
1196	  FAR struct sg2000_eth_priv_s *priv =
1197	      (FAR struct sg2000_eth_priv_s *)dev;
1198	  unsigned int len = netpkt_getdatalen(dev, pkt);
1199	  uint8_t tmp_buf[SG2000_ETH_BUFSIZE];
1200	  const uint8_t *data;
1201	  int ret;
1202	
1203	  if (len > SG2000_ETH_BUFSIZE)
1204	    {
1205	      nerr("ERROR: TX packet too large: %u\n", len);
1206	      netpkt_free(dev, pkt, NETPKT_TX);
1207	      return -E2BIG;
1208	    }
1209	
1210	  /* Extract data from netpkt.  If fragmented, copy out; else use pointer. */
1211	
1212	  if (netpkt_is_fragmented(pkt))
1213	    {
1214	      netpkt_copyout(dev, tmp_buf, pkt, len, 0);
1215	      data = tmp_buf;
1216	    }
1217	  else
1218	    {
1219	      data = netpkt_getdata(dev, pkt);
1220	      if (!data)
1221	        {
1222	          nerr("ERROR: netpkt_getdata returned NULL\n");
1223	          netpkt_free(dev, pkt, NETPKT_TX);
1224	          return -EINVAL;
1225	        }
1226	    }
1227	
1228	  /* Send via DMA */
1229	
1230	  ret = hw_transmit(priv, data, len);
1231	  if (ret < 0)
1232	    {
1233	      nerr("ERROR: hw_transmit failed: %d\n", ret);
1234	      netpkt_free(dev, pkt, NETPKT_TX);
1235	      return ret;
1236	    }
1237	
1238	  /* Track this packet: store it so tx_cleanup can free it after DMA done.
1239	   * The tx_cur was already advanced by hw_transmit, so use (tx_cur - 1).
1240	   */
1241	
1242	  {
1243	    irqstate_t flags = up_irq_save();
1244	    unsigned int slot = (priv->tx_cur - 1) & (TX_RING_SIZE - 1);
1245	
1246	    priv->tx_pkt[slot] = pkt;
1247	    up_irq_restore(flags);
1248	  }
1249	
1250	  return OK;
1251	}
