1253	/****************************************************************************
1254	 * Name: netdriver_receive
1255	 *
1256	 * Description:
1257	 *   OpenVela netdev_ops_s receive callback.  Called by upper half when
1258	 *   netdev_lower_rxready() was signaled.  Returns one received packet, or
1259	 *   NULL if no more packets are available.
1260	 *
1261	 *   Returned Value:
1262	 *     A netpkt_t * containing the received packet, or NULL.
1263	 *
1264	 ****************************************************************************/
1265	
1266	static FAR netpkt_t *netdriver_receive(FAR struct netdev_lowerhalf_s *dev)
1267	{
1268	  FAR struct sg2000_eth_priv_s *priv =
1269	      (FAR struct sg2000_eth_priv_s *)dev;
1270	  FAR netpkt_t *pkt = NULL;
1271	  struct sg2000_dma_desc_s *desc;
1272	  uint32_t status;
1273	  int frame_len;
1274	  int ret;
1275	
1276	  /* Check if there is a completed RX descriptor */
1277	
1278	  desc = &priv->rx_desc[priv->rx_cur];
1279	  if (desc->des0 & DESC_OWN)
1280	    {
1281	      /* DMA still owns it, no packet ready yet.
1282	       * This can happen if rxready was signaled for a previous packet
1283	       * that was already consumed, or in edge cases.
1284	       */
1285	
1286	      return NULL;
1287	    }
1288	
1289	  status = desc->des0;
1290	
1291	  /* Check for errors */
1292	
1293	  if (status & RX_DESC_ES)
1294	    {
1295	      nerr("ERROR: RX error, status=0x%08" PRIX32 "\n", status);
1296	      goto refill;
1297	    }
1298	
1299	  /* Get frame length (includes FCS which we strip) */
1300	
1301	  frame_len = ((status >> RX_DESC_FL_SHIFT) & RX_DESC_FL_MASK) - ETH_FCSSLEN;
1302	
1303	  if (frame_len <= 0 || frame_len > CONFIG_NET_ETH_PKTSIZE)
1304	    {
1305	      nwarn("WARNING: Invalid RX frame length: %d\n", frame_len);
1306	      goto refill;
1307	    }
1308	
1309	  /* Allocate a netpkt for the received data */
1310	
1311	  pkt = netpkt_alloc(dev, NETPKT_RX);
1312	  if (!pkt)
1313	    {
1314	      nerr("ERROR: netpkt_alloc failed\n");
1315	      goto refill;
1316	    }
1317	
1318	  /* Copy data from DMA RX buffer into the netpkt */
1319	
1320	  ret = netpkt_copyin(dev, pkt, priv->rx_buf[priv->rx_cur], frame_len, 0);
1321	  if (ret < 0)
1322	    {
1323	      nerr("ERROR: netpkt_copyin failed: %d\n", ret);
1324	      netpkt_free(dev, pkt, NETPKT_RX);
1325	      goto refill;
1326	    }
1327	
1328	  ninfo("RX packet: %d bytes\n", frame_len);
1329	
1330	refill:
1331	  /* Return the descriptor to DMA (set OWN=1) */
1332	
1333	  desc->des0 = DESC_OWN;
1334	  desc->des1 = RX_BUF_SIZE;
1335	
1336	  priv->rx_cur = (priv->rx_cur + 1) & (RX_RING_SIZE - 1);
1337	  rx_doorbell(priv);
1338	
1339	  return pkt;
1340	}
