1342	/****************************************************************************
1343	 * Private Data - Operations Structure
1344	 *
1345	 * The netdev_ops_s maps our callbacks to the OpenVela lowerhalf API.
1346	 ****************************************************************************/
1347	
1348	static const struct netdev_ops_s g_ops =
1349	{
1350	  netdriver_ifup,     /* ifup */
1351	  netdriver_ifdown,   /* ifdown */
1352	  netdriver_transmit, /* transmit */
1353	  netdriver_receive   /* receive */
1354	  /* addmac, rmmac, ioctl, reclaim are not implemented for this simple
1355	   * Ethernet MAC driver.  They are only required for Wi-Fi or advanced
1356	   * filtering scenarios.
1357	   */
1358	};
