1364	/****************************************************************************
1365	 * Name: sg2000_eth_initialize
1366	 *
1367	 * Description:
1368	 *   Initialize the SG2000 Ethernet driver and register it with the OpenVela
1369	 *   network stack as a netdev_lowerhalf_s device.
1370	 *
1371	 *   Called from board_late_initialize() during system bringup.
1372	 *
1373	 ****************************************************************************/
1374	
1375	int sg2000_eth_initialize(void)
1376	{
1377	  FAR struct sg2000_eth_priv_s *priv = &g_eth_priv;
1378	  FAR struct netdev_lowerhalf_s *dev = &priv->dev;
1379	  int ret;
1380	  uint32_t r1;
1381	  uint32_t r2;
1382	
1383	  if (g_eth_initialized)
1384	    {
1385	      ninfo("SG2000 Ethernet driver already initialized\n");
1386	      return OK;
1387	    }
1388	
1389	  memset(priv, 0, sizeof(*priv));
1390	  priv->gmac_base = SG2000_GMAC_BASE;
1391	  priv->phy_base = SG2000_EPHY_BASE;
1392	  priv->phy_top = SG2000_EPHY_TOP;
1393	
1394	  /* Set a test MAC address (should be replaced with eFuse/OTP value) */
1395	
1396	  priv->mac_addr[0] = 0x02;
1397	  priv->mac_addr[1] = 0x00;
1398	  priv->mac_addr[2] = 0x00;
1399	  priv->mac_addr[3] = 0x00;
1400	  priv->mac_addr[4] = 0x00;
1401	  priv->mac_addr[5] = 0x01;
1402	
1403	  memcpy(dev->netdev.d_mac.ether.ether_addr_octet, priv->mac_addr,
1404	         IFHWADDRLEN);
1405	
1406	  dev->quota[NETPKT_TX] = TX_RING_SIZE / 2;
1407	  dev->quota[NETPKT_RX] = RX_RING_SIZE / 2;
1408	  dev->ops              = &g_ops;
1409	
1410	  priv->irq = SG2000_IRQ_GMAC;
1411	
1412	  ret = netdev_lower_register(dev, NET_LL_ETHERNET);
1413	  if (ret < 0)
1414	    {
1415	      nerr("ERROR: netdev_lower_register failed: %d\n", ret);
1416	      return ret;
1417	    }
1418	
1419	  netdev_lower_carrier_off(dev);
1420	  g_eth_initialized = true;
1421	  ninfo("SG2000 Ethernet driver registered as eth0 (lowerhalf)\n");
1422	
1423	  /* Step 0: Enable GMAC clocks and deassert resets */
1424	
1425	  gmac_clock_enable();
1426	
1427	  /* Step 1: Verify hardware register readability */
1428	
1429	  ret = test_read_hw_feature(priv->gmac_base);
1430	  if (ret < 0)
1431	    {
1432	      nerr("ERROR: HW feature test failed\n");
1433	      return OK;
1434	    }
1435	
1436	  ninfo("HW feature register test PASS\n");
1437	
1438	  /* Step 2: DMA software reset */
1439	
1440	  ret = dma_soft_reset(priv->gmac_base);
1441	  if (ret < 0)
1442	    {
1443	      nerr("ERROR: DMA reset failed\n");
1444	      return OK;
1445	    }
1446	
1447	  ninfo("DMA reset PASS\n");
1448	
1449	  /* Step 3: EPHY reset and PHY ID verification */
1450	
1451	  /* Set MAC core init (PS=MII mode) before MDIO operations */
1452	
1453	  putreg32(GMAC_CORE_INIT, priv->gmac_base + GMAC_CONFIG);
1454	
1455	  ephy_hardware_reset(priv->phy_base, priv->phy_top);
1456	
1457	  {
1458	    uint16_t id1 = mdio_read(priv->gmac_base, 0, 2);
1459	    uint16_t id2 = mdio_read(priv->gmac_base, 0, 3);
1460	    uint32_t phy_id = (id1 << 16) | id2;
1461	
1462	    ninfo("PHY ID = 0x%08" PRIX32 " (expect 0x00435649)\n", phy_id);
1463	
1464	    if (phy_id == 0xffffffff)
1465	      {
1466	        nerr("ERROR: PHY not responding\n");
1467	        return OK;
1468	      }
1469	  }
1470	
1471	  ninfo("PHY ID verification PASS\n");
1472	
1473	  /* Step 3.5: Run full analog tuning via APB now that MDIO is confirmed
1474	   * working.  Matches Linux cv182xa_phy_config_init() which runs as the
1475	   * PHY driver's config_init callback after MDIO bus registration.
1476	   */
1477	
1478	  ephy_full_tuning(priv->phy_base, priv->phy_top);
1479	
1480	  /* Step 4: Allocate DMA descriptor rings and buffers */
1481	
1482	  ret = alloc_dma(priv);
1483	  if (ret < 0)
1484	    {
1485	      nerr("ERROR: alloc_dma failed: %d\n", ret);
1486	      return OK;
1487	    }
1488	
1489	  init_desc_and_dma(priv);
1490	
1491	  /* Readback verification of DMA registers */
1492	
1493	  r1 = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_BASE_ADDR);
1494	  r2 = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_RING_LEN);
1495	
1496	  ninfo("Readback TX_BASE: 0x%08" PRIX32 " (expect 0x%08" PRIX32 ") %s\n",
1497	        r1, priv->tx_desc_phys,
1498	        r1 == priv->tx_desc_phys ? "OK" : "FAIL");
1499	  ninfo("Readback TX_LEN:  %" PRIu32 " (expect %d) %s\n",
1500	        r2, TX_RING_SIZE - 1,
1501	        r2 == (TX_RING_SIZE - 1) ? "OK" : "FAIL");
1502	
1503	  if (r1 != priv->tx_desc_phys || r2 != (TX_RING_SIZE - 1))
1504	    {
1505	      nerr("ERROR: DMA register readback mismatch\n");
1506	      return OK;
1507	    }
1508	
1509	  ninfo("DMA descriptor setup PASS\n");
1510	
1511	  /* Step 5: Initialize PHY and establish link */
1512	
1513	  ret = phy_config_init(priv);
1514	  if (ret < 0)
1515	    {
1516	      nerr("ERROR: PHY init failed: %d\n", ret);
1517	      return OK;
1518	    }
1519	
1520	  if (!priv->link_up)
1521	    {
1522	      nwarn("WARNING: PHY link down; registering eth0 with carrier off\n");
1523	    }
1524	
1525	  /* Step 6: Configure MAC and start DMA */
1526	
1527	  set_mac_addr(priv->gmac_base, priv->mac_addr);
1528	  start_mac_and_dma(priv);
1529	  rx_doorbell(priv);
1530	
1531	  /* Step 7: Register ISR */
1532	
1533	  ret = irq_attach(priv->irq, sg2000_eth_isr, priv);
1534	  if (ret < 0)
1535	    {
1536	      nerr("ERROR: irq_attach failed: %d\n", ret);
1537	      return OK;
1538	    }
1539	
1540	  up_enable_irq(priv->irq);
1541	
1542	  ninfo("IRQ %d enabled\n", priv->irq);
1543	
1544	  if (priv->link_up)
1545	    {
1546	      netdev_lower_carrier_on(dev);
1547	    }
1548	  else
1549	    {
1550	      netdev_lower_carrier_off(dev);
1551	    }
1552	
1553	  return OK;
1554	}
