34	static int cv182xa_read_status(struct phy_device *phydev)
35	{
36		u32 lp_val, lp_val_cap, cap_val, cap_val_temp, i, ramdom_cap;
37		u32 get_random;
38		int err = genphy_read_status(phydev);
39		//pr_notice("link status=%x, retry_time=%x\n", phydev->link, retry_time);
40		if (retry_time > 0)
41			retry_time--;
42	
43		if (phydev->link == 0) {
44			if (retry_time == 0)
45				link_status = 0;
46	
47		} else if (phydev->speed == SPEED_100 && link_status == 0) {
48			link_status = 1;
49			lp_val = phy_read(phydev, 0x5);
50			pr_notice("lp1=%x\n", lp_val);
51			if (phydev->autoneg == AUTONEG_ENABLE && lp_val == 0x4d61) {
52				cap_val = phy_read(phydev, 0x4);
53				pr_notice("cap1=%x\n", cap_val);
54				get_random_bytes(&get_random, sizeof(int32_t));
55				//ramdom_cap = (get_random % 13) << 5;
56				//if(ramdom_cap == 0x160)
57				//{
58				//	ramdom_cap = 0x1e0;
59				//}
60				//cap_val_temp = cap_val & ~0x1e0 | ramdom_cap;
61				ramdom_cap =  get_random & 0xde0 | 0x20;
62				if (ramdom_cap == 0xd60) {
63					pr_notice("ramdom_cap=%x\n\n", ramdom_cap);
64					ramdom_cap = 0xde0;
65				}
66				cap_val_temp = cap_val & ~0xde0 | ramdom_cap;
67				phy_write(phydev, 0x4, cap_val_temp);
68				pr_notice("get_random=%x, ramdom_cap=%x, cap_val_temp=%x\n",
69					 get_random, ramdom_cap, cap_val_temp);
70				for (i = 0; i < 150; i++) {
71					if ((phy_read(phydev, 0x1) & 0x20) == 0)
72						break;
73	
74					mdelay(10);
75					}
76				pr_notice("i=%d\n", i);
77				phy_modify(phydev, MII_BMCR, BMCR_ISOLATE, BMCR_ANENABLE | BMCR_ANRESTART);
78				for (i = 0; i < 1000; i++) {
79					if (phy_read(phydev, 0x1) & 0x20)
80						break;
81					mdelay(10);
82				}
83				lp_val = phy_read(phydev, 0x5);
84				lp_val_cap = lp_val & 0xde0;
85				pr_notice(" %d, link status=%x, lp2=%x\n", i, phy_read(phydev, 0x1), lp_val);
86	
87				if (((phy_read(phydev, 0x1) & 0x4) != 0) && lp_val != 0 && lp_val_cap != ramdom_cap) {
88					retry_time = 10;
89					phy_write(phydev, 0x4, cap_val);
90					phy_modify(phydev, MII_BMCR, BMCR_ISOLATE, BMCR_ANENABLE | BMCR_ANRESTART);
91					for (i = 0; i < 1000; i++) {
92						if (phy_read(phydev, 0x1) & 0x20)
93							break;
94	
95						mdelay(10);
96					}
97					//mdelay(8000);
98					//lp_val = phy_read(phydev, 0x5);
99					pr_notice(" %d, true link status=%x, lp2=%x\n", i,
100						 phy_read(phydev, 0x1), phy_read(phydev, 0x5));
101				} else {
102					phydev->link = 0;
103					link_status = 0;
104					phy_write(phydev, 0x4, cap_val);
105					phy_modify(phydev, MII_BMCR, BMCR_ISOLATE, BMCR_ANENABLE | BMCR_ANRESTART);
106					//err = phy_start_aneg(phydev);
107					//lp_val = phy_read(phydev, 0x5);
108					//pr_notice("lp3=%x\n", lp_val);
109					pr_notice(" %d, false link status=%x, lp2=%x\n", i,
110						 phy_read(phydev, 0x1), phy_read(phydev, 0x5));
111				}
112	
113				//err = genphy_read_status(phydev);
114				//lp_val = phy_read(phydev, 0x5);
115				//pr_notice("lp3=%x\n", lp_val);
116			}
117		}
118		pr_debug("%s, speed=%d, duplex=%d, ", __func__, phydev->speed, phydev->duplex);
119		pr_debug("pasue=%d, asym_pause=%d, autoneg=%d ", phydev->pause, phydev->asym_pause, phydev->autoneg);
120	
121		return err;
122	}
