152		void __iomem *reg_ephy_base = NULL;
153	
154		reg_ephy_top_wrap = ioremap(REG_EPHY_TOP_WRAP, 0x8);
155		if (!reg_ephy_top_wrap) {
156			ret = -EBUSY;
157			goto err_ephy_mem_1;
158		}
159		reg_ephy_base = ioremap(REG_EPHY_BASE, 0x80);
