196	// Efuse register
197		// Set Double Bias Current
198		//Set rg_eth_txitune1  reg_ephy_base + 0x64 [15:8]
199		//Set rg_eth_txitune0  reg_ephy_base + 0x64 [7:0]
200		if ((cvi_efuse_read_from_shadow(0x20) & EPHY_EFUSE_TXITUNE_FLAG) ==
201			EPHY_EFUSE_TXITUNE_FLAG) {
202			val = ((cvi_efuse_read_from_shadow(0x24) >> 24) & 0xFF) |
203					(((cvi_efuse_read_from_shadow(0x24) >> 16) & 0xFF) << 8);
204			writel((readl(reg_ephy_base + 0x64) & ~0xFFFF) | val, reg_ephy_base + 0x64);
