356		writel(0x366E, reg_ephy_base + 0x44);
357		writel(0x0752, reg_ephy_base + 0x48);
358		writel(0x2556, reg_ephy_base + 0x4c);
359		writel(0x2348, reg_ephy_base + 0x50);
360		writel(0x0C30, reg_ephy_base + 0x54);
361	
362		// Switch to MII-page16
363		writel(0x1000, reg_ephy_base + 0x7c);
364	
365		writel(0x1E08, reg_ephy_base + 0x40);
366		writel(0x3868, reg_ephy_base + 0x44);
367		writel(0x1462, reg_ephy_base + 0x48);
368		writel(0x1A0E, reg_ephy_base + 0x4c);
369		writel(0x305E, reg_ephy_base + 0x50);
370		writel(0x2F62, reg_ephy_base + 0x54);
371	
372	// LED
373		// Switch to MII-page1
374		writel(0x0100, reg_ephy_base + 0x7c);
375	
376		// select LED_LNK/SPD/DPX out to LED_PAD
377		writel((readl(reg_ephy_base + 0x68) & ~0x0f00), reg_ephy_base + 0x68);
378	
379		// Switch to MII-page19
380		writel(0x1300, reg_ephy_base + 0x7c);
381		writel(0x0012, reg_ephy_base + 0x58);
382		// set agc max/min swing
383		writel(0x6848, reg_ephy_base + 0x5c);
384	
385		// Switch to MII-page18
386		writel(0x1200, reg_ephy_base + 0x7c);
387	#if IS_ENABLED(CONFIG_ARCH_CV181X)
388		/* mars LPF(8, 8, 8, 8) HPF(-8, 50(+32), -36, -8) */
389		// lpf
390		writel(0x0808, reg_ephy_base + 0x48);
391		writel(0x0808, reg_ephy_base + 0x4c);
392		// hpf
393		writel(0x32f8, reg_ephy_base + 0x50);
394		writel(0xf8dc, reg_ephy_base + 0x54);
395	#elif IS_ENABLED(CONFIG_ARCH_CV180X)
396		/* phobos LPF:(1 8 23 23 8 1) HPF:(-4,58,-45,8,-5, 0) from sean PPT */
397		// lpf
398		writel(0x0801, reg_ephy_base + 0x48);
399		writel(0x1717, reg_ephy_base + 0x4C);
400		writel(0x0108, reg_ephy_base + 0x5C);
401		// hpf
402		writel(0x3afc, reg_ephy_base + 0x50);
403		writel(0x08d3, reg_ephy_base + 0x54);
404		writel(0x00fb, reg_ephy_base + 0x60);
405	#endif
406	
407		// Switch to MII-page0
408		writel(0x0000, reg_ephy_base + 0x7c);
409		// EPHY start auto-neg procedure
410		writel(0x090e, reg_ephy_top_wrap);
411	
412		// from jinyu.zhao
413		/* EPHY is configured as half-duplex after reset, but we need force full-duplex */
414		writel((readl(reg_ephy_base) | 0x100), reg_ephy_base);
415		//writel((readl(reg_ephy_base + 0x10) & ~0x80), reg_ephy_base + 0x10);
416		// switch to MDIO control by ETH_MAC
417		writel(0x0000, reg_ephy_top_wrap + 4);
418		link_status = 0;
419		retry_time = 0;
420		iounmap(reg_ephy_base);
421	err_ephy_mem_2:
422		iounmap(reg_ephy_top_wrap);
423	err_ephy_mem_1:
424		return ret;
425	}
